   360→  // ✅ 改动：使用代理客户端，支持 inputs 对象传参 (query, correction_feedback, previous_result 等)
   361→  async function runDifyWorkflow(inputsOrQuery, appType) {
   362→    let inputs = {};
   363→    if (typeof inputsOrQuery === "string") {
   364→      inputs = { query: inputsOrQuery };
   365→    } else {
   366→      inputs = inputsOrQuery;
   367→    }
   368→
   369→    // 使用代理客户端运行工作流
   370→    const data = await DifyProxyClient.runWorkflow(appType, inputs, { user: USER_ID });
   371→    let outputs = data?.data?.outputs ?? data?.outputs ?? {};
   372→
   373→    // 解析 outputs.text 是否为 JSON string
   374→    let text = outputs.text ?? outputs.result ?? outputs.answer ?? outputs.output ?? "";
   375→    if (typeof text === "string") {
   376→      const parsed = safeJsonParse(text.replace(/```json/g, "").replace(/```/g, ""));
   377→      if (parsed) return { ...parsed, raw: data };
   378→    }
   379→    // 如果 outputs 本身就是对象结构
   380→    if (outputs && (outputs.department || outputs.town || outputs["镇街"] || outputs.dept)) {
   381→      return { ...outputs, raw: data };
   382→    }
   383→    throw new Error("AI 返回格式无法解析");
   384→  }
