     6→const DifyProxyClient = {
     7→  /**
     8→   * 上传文件到 Dify
     9→   * @param {string} appType - 应用类型 (order_recognition, element_extraction, dispatch_assistant, address_recognition)
    10→   * @param {File} file - 文件对象
    11→   * @param {string} user - 用户标识（可选）
    12→   * @returns {Promise<Object>} - 上传响应，包含 file_id
    13→   */
    14→  async uploadFile(appType, file, user = null) {
    15→    const formData = new FormData();
    16→    formData.append("app_type", appType);
    17→    formData.append("file", file);
    18→    if (user) {
    19→      formData.append("user", user);
    20→    }
    21→
    22→    const response = await fetch("/api/dify/upload", {
    23→      method: "POST",
    24→      body: formData,
    25→    });
    26→
    27→    if (!response.ok) {
    28→      const error = await response.text();
    29→      throw new Error(`文件上传失败 (${response.status}): ${error}`);
    30→    }
    31→
    32→    return await response.json();
    33→  },
    34→
    35→  /**
    36→   * 运行工作流（非流式）
    37→   * @param {string} appType - 应用类型
    38→   * @param {Object} inputs - 输入参数
    39→   * @param {Object} options - 可选参数
    40→   * @param {string} options.user - 用户标识
    41→   * @param {string} options.conversationId - 会话ID
    42→   * @returns {Promise<Object>} - 工作流响应
    43→   */
    44→  async runWorkflow(appType, inputs, options = {}) {
    45→    const payload = {
    46→      app_type: appType,
    47→      inputs: inputs,
    48→      response_mode: "blocking",
    49→      user: options.user || null,
    50→      conversation_id: options.conversationId || null,
    51→    };
    52→
    53→    const response = await fetch("/api/dify/workflow", {
    54→      method: "POST",
    55→      headers: {
    56→        "Content-Type": "application/json",
    57→      },
    58→      body: JSON.stringify(payload),
    59→    });
    60→
    61→    if (!response.ok) {
    62→      const error = await response.text();
    63→      throw new Error(`工作流执行失败 (${response.status}): ${error}`);
    64→    }
    65→
    66→    return await response.json();
    67→  },
    68→
    69→  /**
    70→   * 运行工作流（流式）
    71→   * @param {string} appType - 应用类型
    72→   * @param {Object} inputs - 输入参数
    73→   * @param {Object} options - 可选参数
