    91→      },
    92→      body: JSON.stringify(payload),
    93→    });
    94→
    95→    if (!response.ok) {
    96→      const error = await response.text();
    97→      throw new Error(`流式工作流执行失败 (${response.status}): ${error}`);
    98→    }
    99→
   100→    return response;
   101→  },
