    36→function safeJsonParse(str) {
    37→  if (typeof str !== "string") return null;
    38→  const s = str.trim();
    39→  if (!s) return null;
    40→  if (!((s.startsWith("{") && s.endsWith("}")) || (s.startsWith("[") && s.endsWith("]")))) return null;
    41→  try { return JSON.parse(s); } catch { return null; }
