    51→
    52→  let outputs = data?.data?.outputs ?? data?.outputs ?? {};
    53→
    54→  // 1) outputs 已结构化
    55→  if (outputs && (outputs.department || outputs.reason || outputs.history || outputs.rules)) {
    56→    return { raw: data, outputs };
    57→  }
    58→
    59→  // 2) outputs.text/result/answer 是 JSON 字符串
    60→  const maybeText =
    61→    outputs?.text ?? outputs?.result ?? outputs?.answer ?? outputs?.output ?? "";
    62→
    63→  if (typeof maybeText === "string") {
    64→    const parsed = safeJsonParse(maybeText);
    65→    if (parsed) return { raw: data, outputs: parsed };
