   318→      return `<button class="${cls}" data-page="${page}" ${disabled?"disabled":""}>${label}</button>`;
   319→    };
   320→    const maxShow = 7;
   321→    let start = Math.max(1, state.page - Math.floor(maxShow/2));
   322→    let end = Math.min(totalPages, start + maxShow - 1);
   323→    start = Math.max(1, end - maxShow + 1);
   324→
   325→    let html = "";
   326→    html += btn("«", 1, state.page === 1);
   327→    html += btn("‹", Math.max(1, state.page - 1), state.page === 1);
