   329→      html += btn(String(p), p, false, p === state.page);
   330→    }
   331→    html += btn("›", Math.min(totalPages, state.page + 1), state.page === totalPages);
   332→    html += btn("»", totalPages, state.page === totalPages);
   333→
   334→    wrap.innerHTML = html;
