   352→  function safeJsonParse(str) {
   353→    if (typeof str !== "string") return null;
   354→    const s = str.trim();
   355→    if (!s) return null;
   356→    if (!((s.startsWith("{") && s.endsWith("}")) || (s.startsWith("[") && s.endsWith("]")))) return null;
   357→    try { return JSON.parse(s); } catch { return null; }
   358→  }
