/* ================= 工单列表（纯前端本地数据版 + 地址识别 + 智能派单整合） ================= */
(function () {
  // ====== 应用类型配置（不再需要暴露 API 密钥） ======
  const APP_TYPE_ADDRESS = "address_recognition";  // 地址识别
  const APP_TYPE_DISPATCH = "dispatch_assistant";  // 派单助手
  const USER_ID = "frontend-tickets-user";

  // ====== 工单数据（可通过 Excel 上传替换） ======
  let TICKETS = [
