  function esc(s){
    return (s ?? "").toString().replace(/[&<>"']/g, (m)=>({
      "&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"
    }[m]));
  }

  function contains(hay, needle){
    return (hay ?? "").toString().toLowerCase().includes((needle ?? "").toString().toLowerCase());
  }

  function fmtList(arr){
    if(!Array.isArray(arr) || arr.length===0) return "";
