    state.filtered = TICKETS.filter(x => (
      contains(x["主要内容"], q) ||
      contains(x["被反映街乡镇"], q) ||
      contains(x["所在村社区"], q) ||
      contains(x["二级承办单位简称"], q) ||
      contains(x["建议处置部门"], q) ||
      contains(String(x["序号"]), q)
    ));
