  let state = {
    q: "",
    page: 1,
    size: 10,
    filtered: [...TICKETS],
    currentItem: null,
    tempCorrectionRes: null,
    tempDispatchRes: null,
    selected: new Set(),        // 选中的工单序号集合
    batchCancelled: false       // 批量处理取消标志
